using MediatR;using Microsoft.EntityFrameworkCore;using MSA.Contracts;using MSA.EventBusOutbox;using MSA.Infrastrucute.Mediator;using MSA.PaymentService.Infrastructure;using System.Text.Json;
namespace MSA.PaymentService.Application;
public sealed record ConfirmPaymentCommand(string MerchantTradeNo,string ProviderTransactionId,decimal Amount,string Currency,MSA.PaymentCore.PaymentChannel Channel):ICommand<Guid>;
internal sealed class ConfirmPaymentHandler(PaymentDbContext db,IOutboxStore outbox):IRequestHandler<ConfirmPaymentCommand,Guid>{public async Task<Guid> Handle(ConfirmPaymentCommand r,CancellationToken ct){var p=await db.Payments.SingleOrDefaultAsync(x=>x.MerchantTradeNo==r.MerchantTradeNo,ct)??throw new KeyNotFoundException("Payment not found.");if(p.Amount!=r.Amount||!string.Equals(p.Currency,r.Currency,StringComparison.OrdinalIgnoreCase)||p.Channel!=r.Channel)throw new InvalidOperationException("Payment notification does not match the original payment.");if(p.MarkPaid(r.ProviderTransactionId,DateTimeOffset.UtcNow)){var e=new PaymentSucceededIntegrationEvent{OrderId=p.OrderId,PaymentId=p.Id,ProviderTransactionId=r.ProviderTransactionId};outbox.Add(OutboxMessage.Create(e.GetType().AssemblyQualifiedName!,JsonSerializer.Serialize(e,e.GetType())));}return p.Id;}}
public sealed record GetPaymentByOrderQuery(Guid OrderId,string UserId,bool CanReadAll):IQuery<PaymentDto?>;
public sealed record PaymentDto(Guid Id,Guid OrderId,decimal Amount,string Currency,string Channel,string Status,string? PaymentUrl,DateTimeOffset ExpiresOnUtc);
internal sealed class GetPaymentByOrderHandler(PaymentDbContext db):IRequestHandler<GetPaymentByOrderQuery,PaymentDto?>{public Task<PaymentDto?> Handle(GetPaymentByOrderQuery r,CancellationToken ct)=>db.Payments.AsNoTracking().Where(x=>x.OrderId==r.OrderId&&(r.CanReadAll||x.UserId==r.UserId)).Select(x=>new PaymentDto(x.Id,x.OrderId,x.Amount,x.Currency,x.Channel.ToString(),x.Status.ToString(),x.PaymentUrl,x.ExpiresOnUtc)).SingleOrDefaultAsync(ct);}
